#!/usr/bin/env python3
"""Process chat logs JSONL file and create a CSV summary of user messages."""

import json
import csv
import sys

def process_jsonl(input_file, output_file):
    """Read JSONL file, filter user messages, and write CSV summary."""
    user_records = []

    with open(input_file, 'r', encoding='utf-8') as f:
        for line_num, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue

            try:
                record = json.loads(line)
                # Check if this is a user message
                if record.get('role') == 'user':
                    message = record.get('message', '')
                    user_records.append({
                        'id': record.get('id', ''),
                        'role': record.get('role', ''),
                        'message_length': len(message),
                        'has_question_mark': '?' in message
                    })
            except json.JSONDecodeError:
                # Skip malformed lines gracefully
                print(f"Warning: Skipping malformed line {line_num}", file=sys.stderr)
                continue

    # Write CSV output preserving original order
    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        fieldnames = ['id', 'role', 'message_length', 'has_question_mark']
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(user_records)

    print(f"Processed {len(user_records)} user records from {input_file}")
    print(f"CSV summary written to {output_file}")

if __name__ == '__main__':
    input_file = 'chat_logs.jsonl'
    output_file = 'user_messages_summary.csv'
    process_jsonl(input_file, output_file)
EOF
